import React from "react";
import Waveform from "./Waveform";

function EnsineMusica() {
  return (
    <div className="Ensine-Musica">
      <h2>Sobre nós</h2>
      <Waveform />
      <p className="sobre-nos">
        O "Ensine Música" é um espaço dedicado à criatividade, inovação e colaboração no ensino musical. Com o objetivo de inspirar professores de música, oferecemos tutoriais detalhados sobre a criação de jogos, brincadeiras e instrumentos musicais feitos com materiais alternativos, pensando no ensino na educação básica e em espaços educativos diversos.
      </p>
      <p className="sobre-nos">
        Idealizado pelo professor Filipp Sena, docente da Universidade do Estado do Amapá (UEAP), o site nasceu como uma iniciativa para os alunos da turma 20.3 das disciplinas "Produção de Materiais Pedagógicos Musicais" e "Estágio Supervisionado". Aqui, você encontrará os projetos desenvolvidos durante as aulas, compartilhados para estimular novas práticas pedagógicas.
      </p>
      <p className="sobre-nos">
        Nosso compromisso é fortalecer a educação musical por meio de ideias práticas e acessíveis, fomentando a troca de conhecimentos e experiências entre educadores e amantes da música.
      </p>
    </div>
  );
}

export default EnsineMusica;
